mapper.select:
SELECT FROM ts_ad_slot s LEFT JOIN ts_ad_content c ON c.slot_id = s.id AND c.is_deleted = 0
s.is_deleted = 0
AND ( s.slot_code LIKE CONCAT('%', #{query.keyword}, '%') OR s.slot_name LIKE CONCAT('%', #{query.keyword}, '%') )
AND s.slot_type = #{query.slotType}
AND s.status = #{query.status}
GROUP BY s.id, s.slot_code, s.slot_name, s.slot_type, s.width, s.height, s.max_items, s.status, s.description, s.created_at, s.updated_at ORDER BY s.updated_at DESC, s.id DESC

SELECT FROM ts_ad_content c INNER JOIN ts_ad_slot s ON s.id = c.slot_id AND s.is_deleted = 0
c.is_deleted = 0
AND ( c.content_code LIKE CONCAT('%', #{query.keyword}, '%') OR c.title LIKE CONCAT('%', #{query.keyword}, '%') )
AND c.slot_id = #{query.slotId}
AND c.status = #{query.status}
ORDER BY c.updated_at DESC, c.id DESC

SELECT s.id AS slot_id, s.slot_code, s.slot_type, s.width, s.height, s.max_items, c.id AS content_id, c.content_code, c.title, c.subtitle, c.source_type, c.media_type, c.media_url, c.poster_url, c.card_type, c.payload_json, c.image_url, c.action_type, c.action_payload, c.link_type, c.link_value, c.ext_json, r.platform_json, r.audience_type, r.member_level_json, r.user_id_json FROM ts_ad_slot s INNER JOIN ts_ad_content c ON c.slot_id = s.id AND c.is_deleted = 0 AND c.status = 'PUBLISHED' AND (c.start_time IS NULL OR c.start_time <= #{now}) AND (c.end_time IS NULL OR c.end_time >= #{now}) LEFT JOIN ts_ad_delivery_rule r ON r.content_id = c.id WHERE s.is_deleted = 0 AND s.status = 'ENABLED' AND s.slot_code IN
#{slotCode}
ORDER BY s.id ASC, c.sort_order ASC, c.id DESC

mapper.insert:
INSERT IGNORE INTO ts_ad_event (
    event_id, content_id, slot_code, event_type, user_id,
    visitor_id, platform, occurred_at, created_at
) VALUES (
    #{eventId}, #{contentId}, #{slotCode}, #{eventType}, #{userId},
    #{visitorId}, #{platform}, #{occurredAt}, #{createdAt}
)

mapper.select:
SELECT COALESCE(SUM(CASE WHEN event_type = 'IMPRESSION' THEN 1 ELSE 0 END), 0) AS impressions, COALESCE(SUM(CASE WHEN event_type = 'CLICK' THEN 1 ELSE 0 END), 0) AS clicks, CASE WHEN SUM(CASE WHEN event_type = 'IMPRESSION' THEN 1 ELSE 0 END) = 0 THEN 0 ELSE ROUND( SUM(CASE WHEN event_type = 'CLICK' THEN 1 ELSE 0 END) / SUM(CASE WHEN event_type = 'IMPRESSION' THEN 1 ELSE 0 END), 6 ) END AS click_through_rate FROM ts_ad_event
AND slot_code = #{query.slotCode}
AND content_id = #{query.contentId}
AND occurred_at >= #{query.startTime}
AND occurred_at <= #{query.endTime}
